// src/components/Header.jsx
import React, { useEffect, useState, useRef } from 'react';
import SearchBarUnified from './SearchBarUnified';
import { getAudience, setAudience } from '../utils/audience';
import axios from 'axios';

export default function Header() {
  const [aud, setAud] = useState(getAudience() || 'RESIDENT'); // RESIDENT | TOURIST
  const [open, setOpen] = useState(false);
  const [compact, setCompact] = useState(false);
  const headerRef = useRef(null);

  // compact al scrollear
  useEffect(() => {
    const onScroll = () => setCompact(window.scrollY > 0);
    onScroll();
    window.addEventListener('scroll', onScroll, { passive: true });
    return () => window.removeEventListener('scroll', onScroll);
  }, []);

  const applyAudience = (v) => {
    setAudience(v);
    axios.defaults.headers.common['X-Audience'] = v;
    setAud(v);
    setOpen(false);
    // recarga para refrescar secciones/listas con el header correcto
    window.location.reload();
  };

  return (
    <>
      <header className={`cp-header ${compact ? 'compact' : ''}`} ref={headerRef}>
        <div className="cp-header-inner">
          <a href="/" className="cp-brand" aria-label="Conecta Pinamar">
            <img src="/logo.png" alt="" />
          </a>

          <div className="cp-search-outer">
            {/* usamos tu buscador tal cual; el estilo general lo da el fondo amarillo */}
            <SearchBarUnified />
          </div>

          <div className="cp-right">
            <a href="#" className="cp-btn">MIS CUPONES</a>

            <div className="cp-aud">
              <button
                className="cp-aud-pill"
                onClick={() => setOpen((v) => !v)}
                aria-haspopup="menu"
                aria-expanded={open}
                aria-label="Cambiar audiencia"
              >
                {aud === 'RESIDENT' ? 'Residente' : 'Turista'}
              </button>
              {open && (
                <div className="cp-aud-menu" role="menu">
                  <button
                    role="menuitem"
                    onClick={() => applyAudience('RESIDENT')}
                    className={aud === 'RESIDENT' ? 'active' : ''}
                  >
                    Ver como Residente
                  </button>
                  <button
                    role="menuitem"
                    onClick={() => applyAudience('TOURIST')}
                    className={aud === 'TOURIST' ? 'active' : ''}
                  >
                    Ver como Turista
                  </button>
                </div>
              )}
            </div>

            <button className="cp-burger" aria-label="Abrir menú" onClick={() => setOpen(true)}>
              <span></span><span></span><span></span>
            </button>
          </div>
        </div>
      </header>

      {/* Drawer responsive (simple) */}
      <div className={`cp-drawer ${open ? 'open' : ''}`} onClick={() => setOpen(false)}>
        <div className="panel" onClick={(e) => e.stopPropagation()}>
          <h4>Preferencias</h4>
          <div className="aud-switch">
            <button
              onClick={() => applyAudience('RESIDENT')}
              className={aud === 'RESIDENT' ? 'active' : ''}
            >
              Ver como Residente
            </button>
            <button
              onClick={() => applyAudience('TOURIST')}
              className={aud === 'TOURIST' ? 'active' : ''}
            >
              Ver como Turista
            </button>
          </div>
        </div>
      </div>
    </>
  );
}
